import pathlib,json,sys
path=pathlib.Path(sys.argv[1]);rows=[json.loads(line) for line in path.read_text().splitlines() if line.startswith('{')];assert len(rows)==20 and all(r['complete'] and r['cells']==1944 for r in rows);main=next(r for r in rows if r['null']==-1);nulls=[r for r in rows if r['null']>=0];assert sorted(r['null'] for r in nulls)==list(range(19));s={'packet':main['packet'],'maximum':main['maximum'],'null_maxima':[r['maximum'] for r in sorted(nulls,key=lambda r:r['null'])],'tail':(1+sum(r['maximum']>=main['maximum'] for r in nulls))/20,'total_nominal_cells':20*1944,'source_log':str(path)};out=pathlib.Path('exploration/persistent-01/worker-s')/f'S14-packet{main["packet"]}-log-summary.json';out.write_text(json.dumps(s,indent=2)+'\n');print(json.dumps(s,indent=2))
